/* ---------- Attachment tray ---------- */
.atx{display:flex;flex-direction:column;gap:10px}
.atx-drop{display:flex;flex-direction:column;align-items:center;gap:6px;padding:26px 16px;border-radius:16px;background:none;cursor:pointer;position:relative;font-size:13.5px;transition:background .35s,box-shadow .35s,transform .45s var(--ease)}
.atx-drop::before{content:"";position:absolute;inset:0;border-radius:16px;border:1.5px dashed var(--faint);transition:border-color .35s}
.atx-drop:hover,.atx-drop.over{background:var(--accent-bg)}
.atx-drop:hover::before,.atx-drop.over::before{border-color:var(--accent)}
.atx-drop.over{transform:scale(1.015)}
.atx-file{position:absolute;inset:0;opacity:0;cursor:pointer}
.atx-ic{width:34px;height:34px;border-radius:11px;background:var(--surface);box-shadow:var(--shadow);display:grid;place-items:center;color:var(--fg2);transition:transform .45s var(--ease),background .35s,color .35s}
.atx-drop:hover .atx-ic,.atx-drop.over .atx-ic{transform:translateY(-3px);background:var(--surface);color:var(--accent)}
.atx-sample{color:var(--accent);font-weight:500;position:relative;z-index:1}
.atx-list{display:flex;flex-direction:column;gap:6px}
.atx-it{display:flex;align-items:center;gap:10px;padding:8px 8px 8px 10px;border-radius:14px;background:var(--surface);box-shadow:var(--shadow)}
.atx-ti{width:30px;height:30px;border-radius:9px;display:grid;place-items:center;flex:none;font-family:var(--mono);font-size:9.5px;font-weight:600}
.atx-n{flex:1;min-width:0;font-size:13px}
.atx-n span{display:block;font-size:12px;color:var(--muted)}
.atx-ring{width:22px;height:22px}
.atx-ring circle{transition:stroke-dashoffset .3s linear}
.atx-it .ib{width:26px;height:26px}
.atx-sum{font-size:12.5px;text-align:center;min-height:18px}

DM.def('attachment-tray', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{upload}', I('upload'));
  const drop = $('.atx-drop', r), list = $('.atx-list', r), sum = $('.atx-sum', r);
  const kind = n => { const e = (n.split('.').pop() || '').toLowerCase(); return e === 'pdf' ? ['PDF','var(--pr)','var(--pr-bg)'] : /png|jpg|jpeg|gif|webp|fig/.test(e) ? [e.toUpperCase().slice(0,3),'var(--pl)','var(--pl-bg)'] : /csv|xlsx/.test(e) ? ['CSV','var(--pm)','var(--pm-bg)'] : [e.toUpperCase().slice(0,3) || 'TXT','var(--pb)','var(--pb-bg)']; };
  const size = b => b > 1e6 ? (b / 1e6).toFixed(1) + ' MB' : Math.max(1, Math.round(b / 1e3)) + ' KB';
  let read = 0;
  function add(name, bytes, i = 0){
    const k = kind(name);
    const it = html(`<div class="atx-it"><span class="atx-ti" style="color:${k[1]};background:${k[2]}">${k[0]}</span><span class="atx-n">${name.replace(/</g,'&lt;')}<span>${size(bytes)}</span></span><svg class="atx-ring" viewBox="0 0 22 22"><circle cx="11" cy="11" r="8" fill="none" stroke="var(--line)" stroke-width="2"/><circle cx="11" cy="11" r="8" fill="none" stroke="var(--accent)" stroke-width="2" stroke-linecap="round" stroke-dasharray="50.3" stroke-dashoffset="50.3" transform="rotate(-90 11 11)"/></svg><button class="ib" aria-label="Remove" data-tip="Remove">${I('x','xs')}</button></div>`);
    list.appendChild(it); enter(it, i * 80);
    $('.ib', it).onclick = () => { it.classList.add('leave'); setTimeout(() => it.remove(), 320); };
    const ring = $$('circle', it)[1]; let p = 0;
    const iv = c.every(70, () => { p = Math.min(1, p + .04 + Math.random() * .08); ring.style.strokeDashoffset = 50.3 * (1 - p);
      if (p >= 1){ clearInterval(iv); const s = $('.atx-ring', it); s.outerHTML = `<span style="color:var(--ok);display:grid;place-items:center;width:22px">${I('ok')}</span>`; read++; swap(sum, 'The agent can read ' + read + (read > 1 ? ' files' : ' file') + ' now'); } });
  }
  $('.atx-sample', r).onclick = e => { e.preventDefault(); [['brief.pdf', 2.4e6],['Pricing.fig', 8.1e6],['signups.csv', 3.2e5]].forEach((f, i) => add(f[0], f[1], i)); };
  $('.atx-file', r).onchange = e => { Array.from(e.target.files).forEach((f, i) => add(f.name, f.size, i)); e.target.value = ''; };
  ['dragenter','dragover'].forEach(ev => c.on(drop, ev, e => { e.preventDefault(); drop.classList.add('over'); }));
  ['dragleave','drop'].forEach(ev => c.on(drop, ev, () => drop.classList.remove('over')));
  c.on(drop, 'drop', e => { e.preventDefault(); Array.from(e.dataTransfer.files).forEach((f, i) => add(f.name, f.size, i)); });
});
